def build(final=FINAL):
    G = {}
    for k, d in S.items():
        for part, v in d.items(): G['ani_%s_%s' % (k, part)] = v
    names = {}
    for nm in A.load():
        r = A.classify(nm)
        if r and r[1] in CLASSMAP: names.setdefault(r[1], True)
    entry = []
    for c, key in CLASSMAP.items():
        cs = slug(c)
        if not os.path.exists(os.path.join(FINAL, 'animal_%s.txt' % cs)) and not os.path.exists(os.path.join(FINAL, 'animal_%s.txt' % cs.replace('_and_', '_and_'))): continue
        G['ani2_%s_prompt' % cs] = ['__animal_%s__, __ani_%s_group__, __ani_%s_behaviour__, __ani_%s_scene__.' % (cs, key, key, key)]
        G['ani2_%s_young_prompt' % cs] = ['A young __animal_%s__, which is __ani_%s_young__, __ani_%s_scene__.' % (cs, key, key)]
        G['ani2_%s_closeup_prompt' % cs] = ['__animal_%s__, __ani_%s_detail__.' % (cs, key)]
        entry.append(cs)
    G['ani2_prompt'] = ['__ani2_%s_prompt__' % c for c in entry]
    G['ani2_young_prompt'] = ['__ani2_%s_young_prompt__' % c for c in entry]
    G['ani2_closeup_prompt'] = ['__ani2_%s_closeup_prompt__' % c for c in entry]
    for a, d in FARM.items():
        s = slug(a); G['farm_%s' % s] = ['%s, which is %s' % (a[:1].upper() + a[1:], d)]
    G['farm_animal'] = ['__farm_%s__' % slug(a) for a in FARM]; G['farm_activity'] = FARM_ACT; G['farm_interaction'] = INTER
    G['farm_prompt'] = ['__farm_animal__, __farm_activity__, on a working farm.']
    G['farm_person_prompt'] = ['A person, __farm_interaction__. The animal is __farm_animal__.']
    G['farm_person_frame_prompt'] = ['__frame_clarity__ __frame_ratio__ __any_create_random_person_base_short__ __farm_person_prompt__ __frame_person_style__, __frame_person_full__ Lighting is __frame_light__.']
    G['pet_person_prompt'] = ['A person, __farm_interaction__. The animal is __animal_dogs__.', 'A person, __farm_interaction__. The animal is __animal_cats__.']
    G['v61_entry_points'] = ['ani2_prompt', 'ani2_young_prompt', 'ani2_closeup_prompt', 'farm_prompt', 'farm_person_prompt', 'farm_person_frame_prompt', 'pet_person_prompt']
    return G
def run(final): return run_mod(sys.modules[__name__], final)
def export_aoo(out): return export_aoo_mod(build(FINAL), out, skip=('farm_person_frame_prompt',))
if __name__ == '__main__': run(FINAL)
